"""Compare an edge link with the intersection of its endpoint links in a simplicial
complex given by facets, and list the edges for which the two links coincide."""

import random
from dataclasses import dataclass, field

from reasoning_core.template import Config, Entry, Task


def _faces_from_facets(facets):
    """Return the set of all non-empty faces of the complex generated by facets."""
    faces = set()
    for facet in facets:
        f = frozenset(int(v) for v in facet)
        sub = sorted(f)
        n = len(sub)
        for mask in range(1, 1 << n):
            faces.add(frozenset(sub[i] for i in range(n) if mask & (1 << i)))
    return faces


def _link(face, faces):
    """Link of a face: all faces t disjoint from ``face`` whose union is a face."""
    return frozenset(
        t for t in faces
        if face.isdisjoint(t) and frozenset(face | t) in faces
    )


def _satisfying_edges(facets):
    """Sorted list of edges (as 'u-v' strings) whose link equals the intersection
    of the links of its two endpoints.  Uses the exact definition of links, so the
    returned objects are correct by construction."""
    facets = [tuple(sorted(int(v) for v in f)) for f in facets]
    facets = sorted(set(facets))
    faces = _faces_from_facets(facets)
    edges = sorted(
        f for f in faces if len(f) == 2
    )
    result = []
    for e in edges:
        u, v = sorted(e)
        lk_edge = _link(e, faces)
        lk_u = _link(frozenset({u}), faces)
        lk_v = _link(frozenset({v}), faces)
        if lk_edge == lk_u & lk_v:
            result.append(f"{u}-{v}")
    return result


def _answer_from_edges(edges):
    return ",".join(edges) if edges else "none"


@dataclass
class SimplicialLinkConfig(Config):
    n_vertices: int = 8
    n_triangles: int = 10
    facets: list = field(default_factory=list)

    def apply_difficulty(self, level):
        self.n_vertices = 6 + 2 * level
        self.n_triangles = 7 + 4 * level


class SimplicialLinkCondition(Task):
    summary = ("Compare an edge link with the intersection of its endpoint links in "
               "simplicial complexes given by facets; return the candidate contractions "
               "satisfying equality or the obstructing faces.")
    design_choice = ("Return only the list of edges whose link equals the intersection, "
                     "with no obstructing-face detail.")
    config_cls = SimplicialLinkConfig
    task_version = 2

    def _make_facets(self):
        n = self.config.n_vertices
        n_tri = self.config.n_triangles
        triangles = set()
        attempts = 0
        while len(triangles) < n_tri and attempts < 500:
            attempts += 1
            tri = tuple(sorted(random.sample(range(n), 3)))
            triangles.add(tri)
        facets = sorted(triangles)
        if not facets:
            facets = [tuple(sorted((0, 1, 2)))]
        return facets

    def generate_entry(self):
        facets = self._make_facets()
        edges = _satisfying_edges(facets)
        answer = _answer_from_edges(edges)
        facets_render = ";".join("-".join(str(v) for v in f) for f in facets)
        return Entry(
                metadata={
                    "facets": [list(f) for f in facets],
                    "facets_render": facets_render,
                    "n_vertices": self.config.n_vertices,
                    "satisfying_edges": edges,
                },
                answer=answer,
            )

    def render_prompt(self, metadata):
        return (
            "A simplicial complex is given by its maximal faces (facets), each written "
            "as a dash-joined list of vertex numbers; the full complex contains every "
            "non-empty subface of these facets.\n"
            f"Facets: {metadata['facets_render']}.\n"
            "For a face sigma, its link Lk(sigma) is the set of all faces tau disjoint "
            "from sigma such that sigma-union-tau is also a face.  For an edge e={u,v}, "
            "say e satisfies the link condition when Lk(e) equals the intersection "
            "Lk(u) intersect Lk(v).\n"
            "List every edge {u,v} of the complex that satisfies the link condition, "
            "as a comma-separated list of edges written 'u-v' with the smaller vertex "
            "first, in increasing lexicographic order of (u,v).  If no edge satisfies, "
            "answer exactly: none"
        )

    def score_answer(self, answer, entry):
        reference = _answer_from_edges(_satisfying_edges(entry.metadata["facets"]))
        if str(answer).strip() == reference:
            return 1
        return 0


